private def readBooks(resultSet: ResultSet): List[BookRecord] =
  val builder = List.newBuilder[BookRecord]
  while resultSet.next() do builder += readBook(resultSet)
  builder.result()

private def pooledConnectionResource: Resource[IO, Connection] =
  Resource.make {
    dataSourceOrFail.flatMap(dataSource =>
      IO.blocking(dataSource.getConnection)
    )
  } { connection =>
    IO.blocking(connection.close()).handleErrorWith(_ => IO.unit)
  }

def withTransactionConnection[A](operation: Connection => IO[A]): IO[A] =
  pooledConnectionResource.use { connection =>
    for
      _ <- IO.blocking(connection.setAutoCommit(false))
      result <- operation(connection).attempt
      _ <- result match
        case Right(_) => IO.blocking(connection.commit())
        case Left(_) => IO.blocking(connection.rollback()).handleErrorWith(_ => IO.unit)
      value <- IO.fromEither(result)
    yield value

export function useBookList(): BookListState {
  const navigate = useNavigate()
  const [searchParams] = useSearchParams()

  const [books, setBooks] = useState<BookCatalogRecord[]>([])
  const [keyword, setKeyword] = useState('')
  const [inlineMessage, setInlineMessage] = useState('')
  const [isLoading, setIsLoading] = useState(false)

  const highlightedId = searchParams.get('highlight')

  const loadBooks = async () => {
    setIsLoading(true)
    try {
      const response = await sendAPI(new ListBooksAPI())
      setBooks(response.books.map(toBookCatalogRecord))
      setInlineMessage('')
    } catch (error) {
      setInlineMessage(error instanceof Error ? error.message : '图书列表加载失败，请稍后重试。')
    } finally {
      setIsLoading(false)
    }
  }

  useEffect(() => {
    void loadBooks()
  }, [])

  const filteredBooks = useMemo(() => {
    const trimmedKeyword = keyword.trim().toLowerCase()

    if (!trimmedKeyword) {
      return books
    }

    return books.filter((book) =>
      [book.title, book.author, book.categoryLabel, book.isbn, book.id]
        .join(' ')
        .toLowerCase()
        .includes(trimmedKeyword),
    )
  }, [books, keyword])

